-- Wipe the questions, ballots and discussion, seed 250 fresh questions -- ten
-- in each of the 25 country forums -- and create five test agents, one per
-- model, every one small enough for a 12 GB RTX 3060. Pairs with vote_all.py, whose
-- token list matches this one.
--
-- The questions contain non-ASCII text (Türkiye, São Paulo, ...), and
-- Windows PowerShell 5 mangles that when piping into a program. So copy the
-- file into the container and run it there instead:
--
--   docker compose cp reset_and_seed.sql postgres:/tmp/reset_and_seed.sql
--   docker compose exec postgres psql -U vote -d vote -v ON_ERROR_STOP=1 -f /tmp/reset_and_seed.sql
--
-- Run it after the updated app has started once: the app creates the forums
-- table and the 25 country forums at startup, and this file puts questions
-- into them.
--
-- Safe to re-run: it only ever removes the test accounts (@dd.test) and the
-- questions. Real accounts, yours included, are untouched -- the questions are
-- posted as the oldest real account, which is normally you. Forums are kept.
--
-- WARNING: the test accounts have PREDICTABLE tokens (dd-test-01 ... dd-test-05)
-- so the voting script needs no configuration. Fine on localhost, unacceptable
-- on a public instance. Delete them before you publish:
--
--   DELETE FROM users WHERE email LIKE '%@dd.test';

SET client_encoding TO 'UTF8';

BEGIN;

-- The questions are posted by the oldest account that is not a test one. With
-- no such account the insert below would select nothing and quietly create no
-- questions, which looks like success. Fail loudly instead, before anything
-- has been deleted.
DO $guard$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM users WHERE email NOT LIKE '%@dd.test') THEN
        RAISE EXCEPTION 'No real account to author the questions. Register '
                        'yourself on the site first, then run this again.';
    END IF;
END $guard$;

-- The questions go into the country forums, which the app creates when it
-- starts. Without them every question would land in no forum at all.
DO $guard$
BEGIN
    IF to_regclass('forums') IS NULL
       OR (SELECT count(*) FROM forums WHERE kind = 'country') < 25 THEN
        RAISE EXCEPTION 'The country forums are missing. Start the updated app '
                        '(docker compose up -d --build) once, then run this again.';
    END IF;
END $guard$;


-- TRUNCATE rather than DELETE: it does not fire the per-row tally triggers,
-- so this is instant. RESTART IDENTITY puts /i/1 back as the first question.
-- Every table referencing issues is named -- not CASCADE, which would silently
-- empty whatever comes to reference issues next. A new table stops this script
-- with an error instead of being quietly wiped by it.
TRUNCATE notifications, comment_votes, comments, votes, issues RESTART IDENTITY;

-- Old test accounts go, whatever tier created them, so there are never stale
-- agents left voting under a model they no longer run. Their agents cascade.
DELETE FROM users WHERE email LIKE '%@dd.test';

-- --- five test accounts, one model each ---------------------------------------
-- The five strongest general models that fit whole in an RTX 3060's 12 GB,
-- each from a different lab, so a disagreement is between different training
-- rather than between sizes of one family. Every one is under 10 GB at the
-- default 4-bit quantization, leaving room for the context.

CREATE TEMP TABLE test_models (slug text, model text, token text) ON COMMIT DROP;
INSERT INTO test_models VALUES
    ('gemma4-12b',     'gemma4:12b',       'dd-test-01'),   -- Google
    ('qwen35-9b',      'qwen3.5:9b',       'dd-test-02'),   -- Alibaba
    ('ministral3-14b', 'ministral-3:14b',  'dd-test-03'),   -- Mistral
    ('phi4-14b',       'phi4:14b',         'dd-test-04'),   -- Microsoft
    ('granite42-8b',   'granite4.2:8b',    'dd-test-05');   -- IBM

INSERT INTO users (email, email_canonical, display_name, username,
                   password_hash, status, email_verified, note)
SELECT slug || '@dd.test', slug || '@dd.test', slug, slug,
       NULL,                    -- no password: these cannot be logged into
       'approved', true, 'local test agent'
  FROM test_models;

INSERT INTO agents (user_id, name, model_name, token_hash)
SELECT u.id, u.username || '-agent', m.model,
       encode(sha256(m.token::bytea), 'hex')
  FROM test_models m JOIN users u ON u.username = m.slug;

-- --- 250 questions, ten per country forum -------------------------------------
-- Real, current controversies in each country -- the death penalty, abortion,
-- blasphemy and LGBT laws, deportations, conscription, censorship, nuclear
-- power, renamings and flag fights -- written neutrally, with the case for
-- and against in the context. Picked to spread across all four outcomes and
-- to be hard: some are proposals that roll back rights, some are divisive
-- but defensible, some are loud fights over symbols that change little.
--
-- TEST DATA. Clear it before the site goes public: it is deliberately
-- provocative, and it is posted under your account.

INSERT INTO issues (author_id, forum_id, title, body, closes_at, created_at)
SELECT (SELECT id FROM users WHERE email NOT LIKE '%@dd.test'
         ORDER BY id LIMIT 1),
       f.id, t.title, t.body,
       now() + interval '14 days',
       now() - (t.ord * interval '7 minutes')
  FROM (VALUES
 (1,'china',$t$Should China abolish the hukou household registration system nationwide?$t$,$b$Hukou ties access to public schools, healthcare and pensions to a person's registered hometown, leaving many of China's roughly 290 million internal migrant workers with lesser services in cities. Supporters say abolition would reduce inequality and boost consumption; opponents fear overloaded services and fiscal strain on megacities like Beijing and Shanghai.$b$),
 (2,'india',$t$Should India extend caste-based reservations to private-sector jobs?$t$,$b$India reserves government jobs and university seats for Scheduled Castes, Scheduled Tribes and Other Backward Classes, but not private jobs, which now make up most employment. Supporters say caste discrimination persists in private hiring. Businesses and critics argue quotas would hurt competitiveness and that reservations should be based on income instead.$b$),
 (3,'united-states',$t$Should the United States enact a federal ban on abortion after 15 weeks of pregnancy?$t$,$b$Since Dobbs v Jackson in 2022, abortion law is set by states, ranging from near-total bans to broad access. A federal 15-week limit has been proposed in Congress. Supporters say it protects fetal life and sets a national standard. Opponents say it overrides states that protect access and endangers women with late-diagnosed complications.$b$),
 (4,'indonesia',$t$Should Indonesia continue moving its capital from Jakarta to Nusantara in East Kalimantan?$t$,$b$Nusantara was launched to relieve sinking, congested Jakarta and spread development beyond Java, but funding has lagged and investors are scarce. Supporters say it is a long-term fix for Jakarta's flooding and inequality. Critics cite deforestation, Indigenous land loss and huge costs at a time of tight budgets.$b$),
 (5,'brazil',$t$Should Brazil allow Petrobras to drill for oil in the Foz do Amazonas basin?$t$,$b$Petrobras sought for years to drill offshore near the mouth of the Amazon, and the environmental agency Ibama granted a licence in 2025. Supporters say the reserves bring revenue and jobs to Amapa, one of Brazil's poorest states. Opponents cite spill risks to coral reefs and mangroves and the clash with Brazil's climate leadership.$b$),
 (6,'russia',$t$Should Russia bar migrant children from enrolling in state schools unless they pass a Russian language test?$t$,$b$A 2025 rule requires children of foreign nationals to pass a Russian language exam before enrolling in state schools. Supporters say it protects teaching quality and speeds integration. Critics say many Central Asian children are left out of school entirely, which hurts integration and may breach the right to education.$b$),
 (7,'pakistan',$t$Should Pakistan continue deporting undocumented Afghans under the Illegal Foreigners Repatriation Plan?$t$,$b$Since 2023 Pakistan has expelled hundreds of thousands of Afghans, later extending the plan to holders of Proof of Registration cards. The government links some to militancy and says the economy cannot carry them. Critics say many were born in Pakistan and face danger under Taliban rule, especially women and former officials.$b$),
 (8,'mexico',$t$Should Mexico keep electing federal judges and Supreme Court justices by popular vote?$t$,$b$A 2024 constitutional reform made Mexico elect judges by vote, with the first election held in June 2025 on low turnout. Supporters say it fights a corrupt, elite judiciary. Critics say voters cannot judge legal expertise, that candidates were filtered by the ruling party, and that judicial independence is weakened.$b$),
 (9,'japan',$t$Should Japan restart the Kashiwazaki-Kariwa nuclear plant in Niigata, the world's largest?$t$,$b$TEPCO, the operator of Fukushima Daiichi, wants to restart reactors at Kashiwazaki-Kariwa, and Niigata's governor approved it in 2025. Supporters say it cuts imports of fossil fuels and emissions. Opponents cite the Fukushima disaster, earthquake risk, weak evacuation plans, and TEPCO's past safety failures.$b$),
 (10,'nigeria',$t$Should Nigeria amend the constitution to allow each state to create its own police force?$t$,$b$Nigeria's police are controlled only by the federal government. Governors and many lawmakers want state police to fight banditry and kidnapping. Supporters say local forces know local terrain. Opponents fear governors would use them against political rivals and that poorer states cannot afford them.$b$),
 (11,'philippines',$t$Should the Philippines amend the 1987 Constitution to lift the 60/40 limits on foreign ownership?$t$,$b$Charter change would let foreigners fully own firms in more sectors and possibly land. Backers say it would draw investment and jobs; critics fear loss of national control over land and resources and see it as a route to extending politicians' terms.$b$),
 (12,'egypt',$t$Should Egypt keep cutting the subsidy on its baladi bread to shrink the budget deficit?$t$,$b$In 2024 Egypt quadrupled the subsidised loaf price to 20 piastres, the first rise in decades, under IMF-backed reform. Supporters say subsidies drain the budget; critics warn that tens of millions of poor Egyptians rely on the bread to eat.$b$),
 (13,'vietnam',$t$Should Vietnam restart the Ninh Thuan nuclear power project it cancelled in 2016?$t$,$b$In 2024 leaders revived plans for Russian and Japanese-backed reactors in Ninh Thuan. Supporters cite surging power demand and coal reduction; critics raise typhoon and tsunami risk, waste handling, costs and limited independent safety oversight.$b$),
 (14,'germany',$t$Should the German Bundestag ask the Federal Constitutional Court to ban the AfD party?$t$,$b$The domestic intelligence agency classified the AfD as extremist in 2025, and some MPs want a ban case. Supporters say democracy must defend itself; critics say banning the second largest party would anger millions of voters and may fail.$b$),
 (15,'bangladesh',$t$Should Bangladesh keep banning all activities of the Awami League party?$t$,$b$The interim government banned the party's activities in 2025 under anti-terror law pending trials over the 2024 crackdown. Supporters say leaders must face justice first; critics say banning a major party denies millions a vote.$b$),
 (16,'turkey',$t$Should Turkey organise the large-scale return of Syrian refugees to northern Syria now that Assad has fallen?$t$,$b$Turkey hosts roughly three million Syrians under temporary protection. Supporters say the regime change makes return possible and eases pressure on housing and wages. Critics warn that Syria remains unstable, that pressure to leave may not be truly voluntary, and that children raised in Turkey would be uprooted.$b$),
 (17,'iran',$t$Should Iran accept strict limits on uranium enrichment in exchange for US sanctions relief?$t$,$b$After the 2025 strikes on Fordow and Natanz, talks centre on whether Iran should cap or pause enrichment. Supporters say relief would revive an economy hit by inflation. Hardliners say enrichment is a sovereign right under the NPT and that past deals were broken by Washington.$b$),
 (18,'united-kingdom',$t$Should the UK legalise assisted dying for terminally ill adults in England and Wales?$t$,$b$The Terminally Ill Adults (End of Life) Bill would let adults with six months to live seek help to end their lives with safeguards. Supporters cite dignity and choice. Opponents, including many disabled people's groups and doctors, fear pressure on vulnerable people and weak palliative care.$b$),
 (19,'thailand',$t$Should Thailand relist cannabis as a narcotic and ban recreational use after its 2022 decriminalisation?$t$,$b$Thousands of dispensaries opened after cannabis was delisted. The health ministry now limits sales to prescriptions. Supporters of a full ban cite youth use and a lack of regulation. Opponents say it would ruin farmers and shop owners and revive jail for a low-harm drug.$b$),
 (20,'france',$t$Should France legalise assisted dying for adults with serious incurable illnesses?$t$,$b$The National Assembly approved an 'aide a mourir' bill in 2025 allowing patients in advanced stages of incurable illness to request a lethal substance. Supporters cite autonomy and suffering. Religious leaders and palliative care doctors fear it will pressure the elderly and disabled.$b$),
 (21,'italy',$t$Should Italy reintroduce compulsory military or civil service for young people, suspended since 2005?$t$,$b$The League has repeatedly proposed bringing back a short mandatory service for 18-year-olds. Supporters say it would build civic duty and strengthen a thin defence reserve amid European rearmament. Opponents say it is costly, disrupts study and work, and that the armed forces need trained professionals, not short-term conscripts.$b$),
 (22,'south-africa',$t$Should South Africa use the Expropriation Act to take land without compensation where it deems it just and equitable?$t$,$b$The Expropriation Act signed in January 2025 allows nil compensation in limited cases, such as abandoned land. Supporters say land ownership is still deeply skewed by apartheid and reform has been too slow. The DA and farming groups warn it threatens property rights and investment, and it has drawn fierce criticism from the United States.$b$),
 (23,'south-korea',$t$Should South Korea develop its own nuclear weapons to deter North Korea?$t$,$b$Polls regularly show most South Koreans back an independent nuclear arsenal. Supporters say North Korea's growing arsenal and doubts about US commitment leave no choice. Opponents warn it would break the Non-Proliferation Treaty, risk sanctions and nuclear fuel supply, strain the US alliance and spark a regional arms race.$b$),
 (24,'spain',$t$Should Spain's 2024 amnesty law cover Carles Puigdemont and all leaders of the 2017 Catalan independence bid?$t$,$b$The amnesty law, passed in exchange for Junts and ERC support for Pedro Sanchez, erases most offences linked to the 2017 referendum. Supporters say it closes a political conflict and has calmed Catalonia. Opponents say it was traded for votes, undermines equality before the law, and courts have refused to apply it to embezzlement charges.$b$),
 (25,'colombia',$t$Should Colombia legalise recreational cannabis for adults, as proposed in repeated bills in Congress?$t$,$b$Colombia allows personal doses and medical cannabis, but bills to legalise adult recreational use failed narrowly in the Senate in 2023. Supporters say it would weaken armed groups and illegal markets. Opponents, including conservative and religious parties, fear more youth consumption and that cartels would simply move to cocaine.$b$),
 (26,'china',$t$Should China raise the statutory retirement age beyond the limits set in its 2024 reform?$t$,$b$In 2024 China began gradually raising retirement ages to 63 for men and 55 or 58 for women. Some economists argue a faster, higher increase is needed as the population ages and pension funds run short. Critics say it breaks promises to workers in hard manual jobs and worsens already high youth unemployment.$b$),
 (27,'india',$t$Should India adopt One Nation One Election to hold Lok Sabha and state polls together?$t$,$b$A committee led by former President Ram Nath Kovind recommended holding national and state elections simultaneously, and bills were introduced in Parliament in 2024. Supporters say it would cut costs and constant campaigning. Opponents say it weakens federalism, favours national parties and would force early dissolution of state assemblies.$b$),
 (28,'united-states',$t$Should the United States reinstate a national assault weapons ban like the 1994 to 2004 law?$t$,$b$The federal ban on certain semi-automatic rifles and large magazines expired in 2004; such rifles have been used in many mass shootings. Supporters say a ban would reduce deaths in mass attacks. Opponents say it violates the Second Amendment, targets popular legal firearms and has little effect on overall gun crime.$b$),
 (29,'indonesia',$t$Should Indonesia extend its free nutritious meals programme to all schoolchildren and pregnant women?$t$,$b$President Prabowo Subianto's flagship programme aims to feed tens of millions of people daily. Supporters say it tackles child stunting, which affects about a fifth of young children. Critics point to budget cuts elsewhere, mass food poisoning incidents at some kitchens and a large role for the military in delivery.$b$),
 (30,'brazil',$t$Should Brazil pave the BR-319 highway linking Manaus to Porto Velho through the Amazon?$t$,$b$The BR-319 is largely an unpaved road cutting through one of the most intact parts of the Amazon. Supporters say Manaus needs a reliable road link, especially during droughts that close rivers. Scientists warn paving would open a new front of illegal logging, land grabbing and deforestation.$b$),
 (31,'russia',$t$Should Russia keep year-round military conscription instead of the traditional spring and autumn call-ups?$t$,$b$A law passed in 2025 lets military enlistment offices call up and process conscripts all year from 2026, not only in two seasonal campaigns. Backers say it spreads the workload and fills units steadily during the war in Ukraine. Opponents say it removes predictable windows for young men and makes it easier to call people up with little notice.$b$),
 (32,'pakistan',$t$Should Pakistan keep Tehreek-e-Labbaik Pakistan banned as a proscribed organisation?$t$,$b$The government banned the TLP again in 2025 after violent protests, having lifted an earlier 2021 ban. Supporters say the party uses street violence and blasphemy agitation to coerce the state. Critics say banning a party that won millions of votes is undemocratic and risks pushing its supporters underground.$b$),
 (33,'mexico',$t$Should Mexico keep the National Guard under the control of the army, SEDENA?$t$,$b$A 2024 reform placed the National Guard, created as a civilian police force, under the Defence Ministry. Supporters say the army is the only institution able to confront cartels. Critics and human rights groups warn about militarisation of policing, a record of abuses, and weak civilian oversight.$b$),
 (34,'japan',$t$Should Japan amend Article 9 of its constitution to explicitly recognise the Self-Defense Forces?$t$,$b$Article 9 renounces war, and the LDP has long proposed adding a clause naming the Self-Defense Forces. Supporters say it ends doubt about the forces' constitutionality amid threats from China and North Korea. Opponents fear it opens the way to wider military action and a break with the pacifist postwar order.$b$),
 (35,'nigeria',$t$Should Nigeria bring back the petrol subsidy that President Tinubu removed in 2023?$t$,$b$Removing the fuel subsidy saved the government trillions of naira but tripled petrol prices and deepened a cost of living crisis. Supporters of reinstatement say ordinary Nigerians cannot cope. Opponents say the subsidy was riddled with fraud, drained public finances, and mostly benefited smugglers and the wealthy.$b$),
 (36,'philippines',$t$Should the Philippines make ROTC mandatory again for all college students?$t$,$b$Senate bills would restore compulsory Reserve Officers' Training Corps, optional since 2002. Supporters cite defence needs in the West Philippine Sea and discipline; opponents point to past hazing, abuse cases and costs to students.$b$),
 (37,'egypt',$t$Should Egypt complete the Rosatom-built El Dabaa nuclear power plant?$t$,$b$El Dabaa on the Mediterranean coast is financed mostly by a large Russian loan. Backers say it gives stable low-carbon power for a growing population; critics cite debt burden, dependence on Russia, water use and nuclear safety oversight.$b$),
 (38,'vietnam',$t$Should Vietnam let its own citizens gamble in casinos across the country?$t$,$b$Vietnamese are mostly barred from casinos, except in a pilot at Phu Quoc and Van Don. Extending access could keep money from Cambodian border casinos and raise tax; critics warn of gambling addiction, debt and money laundering.$b$),
 (39,'germany',$t$Should Germany bring back compulsory military service for young men?$t$,$b$Conscription was suspended in 2011. A 2025 law created a voluntary model with mandatory screening that can turn compulsory if too few sign up. Supporters cite the Russian threat; critics cite youth freedom and ask why only men.$b$),
 (40,'bangladesh',$t$Should Bangladesh complete the Rooppur nuclear power plant built by Russia?$t$,$b$Rooppur, financed by a large Russian loan, is Bangladesh's first nuclear plant. Supporters cite power shortages and gas depletion; critics cite debt, corruption claims tied to the former government and safety near the Padma river.$b$),
 (41,'turkey',$t$Should Turkey build a second nuclear power plant at Sinop on the Black Sea coast?$t$,$b$After Akkuyu, the government wants a Sinop plant to cut reliance on imported Russian gas and Azerbaijani oil. Backers cite energy security and low emissions. Opponents point to seismic risk, waste storage, dependence on foreign builders and local protests over the Black Sea environment.$b$),
 (42,'iran',$t$Should Iran cut gasoline subsidies and raise fuel prices toward market levels?$t$,$b$Iran has some of the cheapest petrol in the world, costing billions in subsidies and fuelling smuggling. Economists say reform is unavoidable. The 2019 price rise triggered nationwide protests and a deadly crackdown, and poorer families would be hit hardest without cash compensation.$b$),
 (43,'united-kingdom',$t$Should the UK introduce a mandatory digital ID for everyone with the right to work?$t$,$b$The government announced a digital ID scheme in 2025, partly to curb illegal working. Supporters say it simplifies checks and reduces fraud. Critics warn of cost, data breaches, function creep and exclusion of people without smartphones, and petitions against it drew millions of signatures.$b$),
 (44,'thailand',$t$Should Thailand end compulsory military conscription and move to an all-volunteer army?$t$,$b$Young Thai men face an annual lottery that can send them into service for up to two years, with reports of abuse of conscripts. Reformers say a volunteer force would be more professional. The army argues conscription is needed, especially after the 2025 border clashes with Cambodia.$b$),
 (45,'france',$t$Should France ban the Islamic headscarf in all sports competitions, including amateur leagues?$t$,$b$The Senate backed a bill in 2025 to prohibit conspicuous religious symbols in competitive sport. Supporters say it defends laicite and neutral sport. Opponents say it would exclude Muslim women from local clubs and extends secularism rules meant for the state to private citizens.$b$),
 (46,'italy',$t$Should Italy return to nuclear power by building new small modular reactors?$t$,$b$Italy shut its last plants after the 1987 and 2011 referendums, but the Meloni government has approved an enabling law to restart nuclear. Backers cite energy security, low emissions and high electricity prices. Critics point to two referendum votes against it, waste storage with no national site, seismic risk and long, costly build times.$b$),
 (47,'south-africa',$t$Should South Africa implement National Health Insurance, replacing most private medical scheme cover?$t$,$b$The NHI Act, signed in 2024, would create a single state fund buying healthcare for everyone, limiting medical aids to services NHI does not cover. Supporters say it ends a two-tier system where most people rely on weak public clinics. Business, doctors and the DA say it is unaffordable and the state lacks capacity to run it.$b$),
 (48,'south-korea',$t$Should South Korea sharply increase medical school admissions to address its doctor shortage?$t$,$b$The 2024 plan to add 2,000 medical school places triggered mass walkouts by trainee doctors, and was later rolled back. Supporters say rural areas and essential specialties like paediatrics face serious shortages. Doctors say training quality would suffer and the real problem is pay and legal risk in essential fields.$b$),
 (49,'spain',$t$Should Spain extend the life of the Almaraz nuclear plant beyond its planned 2027 to 2028 closure?$t$,$b$Spain plans to phase out nuclear by 2035, starting with Almaraz in Extremadura. After the April 2025 blackout, utilities and the PP pushed for an extension. Supporters say nuclear provides stable low-carbon power. The government and environmental groups say renewables and storage can replace it and owners want lower taxes, not safety.$b$),
 (50,'colombia',$t$Should Colombia offer reduced sentences to criminal gangs under Gustavo Petro's Total Peace policy?$t$,$b$Total Peace seeks negotiations with the ELN, FARC dissident factions and urban gangs, with legal benefits in exchange for disarming. Supporters say military force alone has failed for decades. Critics note violence and armed group recruitment have grown in regions like Catatumbo and say gangs used talks to expand territory.$b$),
 (51,'china',$t$Should China approve its first inland nuclear power plants along the Yangtze River?$t$,$b$China's reactors are all coastal; inland projects in provinces like Hunan and Hubei have been on hold since Fukushima. Backers say they would cut coal use in central China and ease power shortages. Opponents cite risks to drinking water for hundreds of millions of people downstream and cooling-water shortages during droughts.$b$),
 (52,'india',$t$Should India enact a nationwide Uniform Civil Code replacing religious personal laws?$t$,$b$India lets Hindus, Muslims, Christians and others follow separate personal laws on marriage, divorce and inheritance. Uttarakhand passed a Uniform Civil Code in 2024. Supporters say one law would advance gender equality. Many Muslim groups and some tribal communities see it as an attack on religious freedom and cultural autonomy.$b$),
 (53,'united-states',$t$Should the United States keep broad tariffs of 10 percent or more on nearly all imports?$t$,$b$Since 2025 the US has imposed wide baseline tariffs on imports from most countries. Supporters say they protect American manufacturing and give leverage in trade talks. Economists and many businesses say they raise consumer prices, invite retaliation against farmers and exporters, and rest on disputed emergency powers.$b$),
 (54,'indonesia',$t$Should Indonesia keep its ban on exporting raw nickel ore to force processing at home?$t$,$b$Indonesia banned nickel ore exports in 2020, attracting billions in smelter investment, largely Chinese, and making it a key battery supplier. Supporters say it builds industry and jobs. Critics cite coal-powered smelters, deforestation in Sulawesi and Halmahera, worker deaths and a WTO ruling against the ban.$b$),
 (55,'brazil',$t$Should Brazil end the six-day work week under the proposed amendment to abolish the 6x1 schedule?$t$,$b$A constitutional amendment backed by the VAT movement would end the common six days on, one day off schedule and cut the maximum week from 44 hours. Supporters say workers need rest and time with family. Businesses, especially retail and small firms, warn of higher costs, lost jobs and more informal work.$b$),
 (56,'russia',$t$Should Russia ban the niqab and other face-covering clothing in public places nationwide?$t$,$b$After the 2024 attacks in Dagestan, the region's muftiate briefly banned the niqab and Duma deputies proposed a federal ban. Supporters cite security and facial identification. Opponents, including Chechen leader Ramzan Kadyrov and Muslim clerics, say it targets a small religious minority and interferes with freedom of religion.$b$),
 (57,'pakistan',$t$Should Pakistan carve a separate South Punjab province out of Punjab?$t$,$b$Parties have promised a South Punjab province for years, centred on Multan and Bahawalpur. Backers say the region is neglected by Lahore and needs its own budget and government. Opponents worry about new administrative costs, disputes over boundaries and water, and that it will spur demands to split other provinces.$b$),
 (58,'mexico',$t$Should Mexico require a biometric CURP ID with photo and fingerprints for all residents?$t$,$b$2025 laws make the CURP identity code include biometric data and link it to phone lines and services. The government says it will help find missing people and fight fraud and extortion. Critics warn of mass surveillance, data leaks and exclusion of people who cannot register.$b$),
 (59,'japan',$t$Should Japan pass an anti-espionage law allowing prosecution of people spying for foreign powers?$t$,$b$Japan has no general spying law, and several parties have pledged one since 2025. Supporters say Japan is a soft target for Chinese, Russian and North Korean intelligence. Opponents fear the law could be used against journalists, activists and foreign residents and that its scope could grow over time.$b$),
 (60,'nigeria',$t$Should Nigeria's northwest states negotiate peace deals and amnesty with armed bandit groups?$t$,$b$States like Katsina and Zamfara have tried deals offering bandits amnesty in exchange for laying down arms. Supporters say military force alone has failed and deals save lives. Critics say earlier deals collapsed, rewarded killers and kidnappers, and left victims without justice.$b$),
 (61,'philippines',$t$Should the Philippines revive the mothballed Bataan Nuclear Power Plant?$t$,$b$The plant, built under Marcos Sr, never operated. Reviving it or building new reactors could cut costly imported fuel use and emissions; critics cite fault lines, volcano risk near Mount Natib, waste storage and the plant's corruption-tainted history.$b$),
 (62,'egypt',$t$Should Egypt allow Palestinians fleeing Gaza to shelter in North Sinai?$t$,$b$Egypt has refused mass entry through Rafah, saying it would enable permanent displacement and threaten its security. Humanitarian groups say civilians need refuge from war; Egypt and Arab states fear it would help empty Gaza for good.$b$),
 (63,'vietnam',$t$Should Vietnam fully ban the sale and use of e-cigarettes and heated tobacco?$t$,$b$The National Assembly voted in late 2024 to ban these products from 2025. Health officials cite teen vaping and poisonings from spiked liquids; critics say bans push users to black markets and to cigarettes, which cause more harm.$b$),
 (64,'germany',$t$Should Germany restart the nuclear reactors it shut down in April 2023?$t$,$b$Germany closed its last three reactors amid an energy crunch. Restarting could cut coal use and power prices; operators say the plants are being dismantled, restart would be costly and slow, and the waste storage question is unsolved.$b$),
 (65,'bangladesh',$t$Should Bangladesh abolish all remaining civil service job quotas, including for freedom fighters' families?$t$,$b$Protests in 2024 over quotas toppled the government; courts cut quotas to 7 percent. Some want none at all. Supporters want pure merit; others say indigenous, disabled and rural applicants need some reserved places.$b$),
 (66,'turkey',$t$Should Turkey pass laws letting disarmed PKK members return to civilian life under the peace process?$t$,$b$After the PKK announced it would disband in 2025, a parliamentary commission is weighing legal steps for fighters who lay down arms. Supporters say reintegration is needed to end a 40-year conflict. Critics, including many families of soldiers killed, see it as an amnesty for serious violence.$b$),
 (67,'iran',$t$Should Iran let conscripts buy exemption from compulsory military service for a fee?$t$,$b$Men face roughly two years of mandatory service. Paid exemption schemes have been debated and partly used. Supporters say it raises revenue and frees skilled workers. Critics say it lets the wealthy avoid duties that poorer young men cannot escape.$b$),
 (68,'united-kingdom',$t$Should the UK send refused asylum seekers who arrive by small boat to return hubs in third countries?$t$,$b$After scrapping the Rwanda plan, ministers explored return hubs abroad for people whose claims fail. Supporters say it would deter Channel crossings. Critics say it risks breaching refugee law, is costly, and moves responsibility to countries with weaker protections.$b$),
 (69,'thailand',$t$Should Thailand legalise casinos inside large entertainment complexes to boost tourism?$t$,$b$A 2025 bill would have allowed licensed casinos in integrated resorts. Supporters say it would bring investment and tax revenue now lost to illegal gambling and neighbouring countries. Opponents warn of addiction, money laundering and corruption, and the bill was withdrawn amid protests.$b$),
 (70,'france',$t$Should France make its Service national universel mandatory for all 16-year-olds?$t$,$b$The SNU began as a voluntary civic and military-style programme. Making it compulsory has been proposed to build cohesion and resilience amid war in Ukraine. Critics call it costly, poorly run and a form of youth conscription, while teachers' unions object to lost school time.$b$),
 (71,'italy',$t$Should Italy's Parliament pass a national law regulating medically assisted suicide?$t$,$b$Constitutional Court ruling 242 of 2019 allows assisted suicide under strict conditions, but Parliament never legislated, so regions like Tuscany wrote their own rules. A law would give patients clear, uniform access. Catholic groups and disability advocates fear pressure on vulnerable people and argue palliative care should come first.$b$),
 (72,'south-africa',$t$Should South Africa fully decriminalise sex work as proposed in the Criminal Law Amendment Bill?$t$,$b$A 2022 draft bill would remove criminal penalties for selling and buying sex between adults. Supporters, including health bodies, say it reduces HIV risk, police abuse and violence against sex workers. Opponents, including some church and women's groups, say it would expand trafficking and exploitation and prefer the Nordic model.$b$),
 (73,'south-korea',$t$Should South Korea legalise medically assisted dying for terminally ill patients?$t$,$b$A 2022 bill in the National Assembly proposed physician-assisted death, and polls show strong public support. Korea already allows withdrawing life support. Supporters cite suffering and patient autonomy. Doctors, religious groups and critics note Korea's very high elderly suicide and poverty rates and fear pressure on vulnerable patients.$b$),
 (74,'spain',$t$Should Spain grant Catalonia a singular financing deal letting it collect and manage all its own taxes?$t$,$b$The PSOE agreed with ERC to move Catalonia toward a Basque-style model where the Generalitat collects all taxes and pays the state for shared services. Supporters say Catalonia contributes far more than it receives. Other regions, including PSOE-led ones, say it breaks fiscal solidarity and would leave poorer regions with less funding.$b$),
 (75,'colombia',$t$Should Colombia ban fracking and stop signing new oil and gas exploration contracts?$t$,$b$President Petro has halted new exploration contracts as part of an energy transition, and bills to ban fracking have been debated in Congress. Supporters cite climate and water protection. Critics say oil funds a large share of state revenue and exports, gas reserves are falling, and Colombia is starting to import gas at higher cost.$b$),
 (76,'china',$t$Should China punish speech that hurts the feelings of the Chinese nation, as in its 2023 draft law?$t$,$b$A 2023 draft revision of the Public Security Administration Punishments Law proposed detention and fines for speech or clothing deemed to harm the spirit or feelings of the Chinese nation. Supporters framed it as protecting national dignity. Legal scholars warned the wording was vague and open to arbitrary use, and the clause was dropped after public criticism.$b$),
 (77,'india',$t$Should Indian states be allowed to bulldoze homes of people accused of crimes?$t$,$b$Authorities in Uttar Pradesh, Madhya Pradesh and elsewhere have demolished houses of people accused of rioting or other crimes, often Muslims, citing illegal construction. Supporters call it tough deterrence. In 2024 the Supreme Court ruled such punitive demolitions unlawful, saying they punish families without trial.$b$),
 (78,'united-states',$t$Should the United States end birthright citizenship for children of undocumented immigrants?$t$,$b$The Fourteenth Amendment has long been read to grant citizenship to nearly everyone born on US soil, and a 2025 executive order sought to deny it to some children of undocumented or temporary residents. Supporters say it discourages illegal migration. Opponents say it defies the Constitution and would create stateless children.$b$),
 (79,'indonesia',$t$Should Indonesia enforce its new criminal code ban on sex and cohabitation outside marriage?$t$,$b$Indonesia's revised criminal code, taking effect in 2026, punishes sex outside marriage and unmarried cohabitation, prosecuted on complaint by a spouse, parent or child. Supporters say it upholds religious and family values. Critics say it invades privacy and could be used against LGBT people, couples in religious marriages and tourists.$b$),
 (80,'brazil',$t$Should Brazil adopt the marco temporal limiting Indigenous land claims to lands occupied in 1988?$t$,$b$The marco temporal thesis says Indigenous peoples can only claim lands they occupied when the 1988 constitution was enacted. The Supreme Court rejected it in 2023, but Congress passed it into law. Agribusiness says it gives legal certainty. Indigenous groups say it ignores those expelled before 1988 and threatens forests.$b$),
 (81,'russia',$t$Should Russia ban abortions in private clinics across all regions of the country?$t$,$b$Several regions, including Kursk and Tver, have pushed private clinics to give up abortion licences, and federal bills propose a nationwide ban. Supporters say it will raise the birth rate. Critics say it pushes women toward fewer, overloaded state hospitals or unsafe options and has little effect on birth rates.$b$),
 (82,'pakistan',$t$Should Pakistan keep tougher prison terms for insulting the companions of the Prophet?$t$,$b$A 2023 amendment raised the penalty for derogatory remarks about the Prophet's companions and family to at least ten years. Supporters say it prevents sectarian provocation. Critics, including Shia groups and rights bodies, say blasphemy laws are widely misused for personal disputes and against minorities, and this widens them.$b$),
 (83,'mexico',$t$Should Mexico abolish its independent transparency institute INAI and move its work to the executive?$t$,$b$The 2024 reform dissolved INAI, which handled freedom of information and data protection, and moved its duties to government bodies. Supporters say it cuts costs and duplication. Critics say the government now judges requests about itself, weakening journalists and citizens trying to expose corruption.$b$),
 (84,'japan',$t$Should Japan restrict welfare payments for foreign permanent residents to Japanese citizens only?$t$,$b$Parties such as Sanseito have called for limiting public assistance to Japanese citizens. Supporters say welfare should go to citizens first. Opponents note foreign residents pay taxes and social insurance, that a 1954 notice allows aid to them, and that cuts would hit long-term residents including Korean families living in Japan for generations.$b$),
 (85,'nigeria',$t$Should Nigeria pass the National Commission for the Prohibition of Hate Speech Bill with its death penalty?$t$,$b$A Senate bill first proposed in 2019 included death by hanging for hate speech that leads to death. Supporters say ethnic and religious incitement fuels deadly violence. Critics say hate speech is vaguely defined, that the law would be used against journalists and critics, and that the death penalty is extreme.$b$),
 (86,'philippines',$t$Should the Philippines reinstate the death penalty for large-scale drug trafficking?$t$,$b$Capital punishment was abolished in 2006 and bills to restore it for drug crimes keep returning. Supporters say it would deter syndicates; opponents cite wrongful convictions, a weak justice system that hits the poor hardest, and treaty obligations.$b$),
 (87,'egypt',$t$Should Egypt keep prosecuting people for contempt of religion under Article 98(f) of its Penal Code?$t$,$b$The article punishes insulting heavenly religions with up to five years in prison. Supporters say it protects faith and social peace; rights groups say it is used mostly against Christians, atheists, Shia Muslims and online critics.$b$),
 (88,'vietnam',$t$Should Vietnam keep prosecuting online critics under Article 331 on abusing democratic freedoms?$t$,$b$Article 331 punishes abusing freedoms to infringe the state's interests with up to seven years. Authorities say it prevents disinformation; rights groups say it is used to jail bloggers, Facebook users and activists for peaceful criticism.$b$),
 (89,'germany',$t$Should Germany adopt the AfD proposal for large-scale remigration of people with foreign roots?$t$,$b$Remigration, backed by parts of the AfD, calls for mass removal of migrants, including some citizens seen as not assimilated. Backers frame it as restoring identity; critics say it violates equality under the Basic Law and targets citizens by origin.$b$),
 (90,'bangladesh',$t$Should Bangladesh pass a blasphemy law with the death penalty as Hefazat-e-Islam demands?$t$,$b$Hefazat has long demanded capital punishment for insulting Islam or the Prophet. Supporters say it would curb provocation and mob anger; critics say such laws are abused against minorities and bloggers and would encourage vigilante violence.$b$),
 (91,'turkey',$t$Should Turkey reinstate the death penalty, abolished in 2004, for terrorism and child murder?$t$,$b$President Erdogan and the MHP have repeatedly raised bringing back capital punishment. Supporters say some crimes deserve the ultimate penalty. Opponents note it would end EU accession talks, breach Council of Europe obligations and risk irreversible miscarriages of justice in a strained judiciary.$b$),
 (92,'iran',$t$Should Iran enforce the Hijab and Chastity Law with heavy fines, travel bans and prison for unveiled women?$t$,$b$Parliament passed the law in 2024 but its implementation was paused after public backlash. Supporters say it upholds Islamic law. Opponents say it punishes women for their clothing, relies on surveillance and informants, and would escalate the conflict that followed the 2022 protests.$b$),
 (93,'united-kingdom',$t$Should the UK leave the European Convention on Human Rights to control deportations?$t$,$b$The Conservatives and Reform UK back leaving the ECHR. Supporters say Strasbourg rulings block removals. Opponents say it would weaken rights protections for everyone, put the Good Friday Agreement at risk and place Britain alongside Russia and Belarus outside the convention.$b$),
 (94,'thailand',$t$Should Thailand resume executions for drug trafficking under its death penalty laws?$t$,$b$Thailand has carried out only one execution since 2009, but courts still hand down death sentences. Supporters say executions would deter methamphetamine trafficking. Opponents say evidence of deterrence is weak and that low-level couriers from poor backgrounds are the ones most often sentenced.$b$),
 (95,'france',$t$Should France end birthright citizenship (droit du sol) nationwide, as already done in Mayotte?$t$,$b$Mayotte's rules were tightened in 2025 and the Rassemblement National and parts of the right want abolition across France. Supporters say it would curb irregular migration. Opponents say children born and raised in France would be left without citizenship, breaking a republican tradition.$b$),
 (96,'italy',$t$Should Italy expand its migrant processing and detention centres in Albania at Gjader and Shengjin?$t$,$b$Under the 2023 Italy-Albania protocol, migrants rescued at sea are sent to Italian-run centres in Albania. The government says it deters crossings. Courts have repeatedly blocked detentions, the centres have held few people at very high cost, and rights groups say offshore detention weakens asylum safeguards and access to lawyers.$b$),
 (97,'south-africa',$t$Should South Africa amend the Constitution to reinstate the death penalty for murder and rape?$t$,$b$The Constitutional Court abolished capital punishment in 1995 in S v Makwanyane. Parties such as the ATM and some ActionSA figures call for its return given very high violent crime. Opponents say it does not deter crime, the justice system makes errors, it would breach the Bill of Rights, and it would fall hardest on poor defendants.$b$),
 (98,'south-korea',$t$Should South Korea resume executions of prisoners on death row?$t$,$b$Korea has not executed anyone since 1997 and is considered abolitionist in practice, though around 60 people remain under death sentence. After several mass stabbings, some politicians called for executions to resume. Opponents say it would breach Korea's human rights commitments, risk wrongful deaths and harm ties with the EU.$b$),
 (99,'spain',$t$Should Spain allow town councils like Jumilla to ban Muslim religious celebrations in municipal sports facilities?$t$,$b$In 2025 Jumilla in Murcia, governed by the PP with Vox support, barred religious events such as Eid prayers from public sports centres, used for years by the local Muslim community. Backers call it protecting Spanish identity. The government, bishops and Muslim groups said it targets one faith and breaches constitutional religious freedom.$b$),
 (100,'colombia',$t$Should Colombia resume aerial spraying of glyphosate to destroy coca crops?$t$,$b$Colombia stopped aerial spraying in 2015 over health concerns, and the Constitutional Court imposed strict conditions to restart it. With coca cultivation at record levels, some politicians want it back. Opponents cite health risks to rural communities, damage to legal crops and water, and evidence that farmers simply replant elsewhere.$b$),
 (101,'china',$t$Should China expand state boarding schools that enrol most Tibetan children away from home?$t$,$b$UN experts estimate around a million Tibetan children attend state boarding schools, many from primary age. Officials say the schools give children in remote areas better education and Mandarin skills. Critics say separating young children from families erodes the Tibetan language and culture and removes parental choice.$b$),
 (102,'india',$t$Should India carry out a nationwide National Register of Citizens like the one in Assam?$t$,$b$Assam's NRC left about 1.9 million people off the final list, many unable to produce old documents. Supporters of a national version say it would identify undocumented migrants. Critics say it would put the burden of proof on poor citizens, and combined with the Citizenship Amendment Act could leave Muslims uniquely at risk of statelessness.$b$),
 (103,'united-states',$t$Should the United States deport migrants to third-country prisons like El Salvador's CECOT without hearings?$t$,$b$In 2025 the US sent hundreds of Venezuelan men to El Salvador's CECOT mega-prison under the Alien Enemies Act, many without a chance to contest gang allegations. Supporters say it removes dangerous gang members quickly. Critics say it denies due process and has sent people with no criminal record to harsh conditions.$b$),
 (104,'indonesia',$t$Should Indonesia keep prison terms for blasphemy against recognised religions?$t$,$b$Indonesia's blasphemy provisions have jailed people including former Jakarta governor Basuki Tjahaja Purnama, and are carried into the new criminal code. Supporters say they protect religious harmony. Critics say they are mostly used against religious minorities such as Ahmadis and Shia Muslims and punish peaceful speech.$b$),
 (105,'brazil',$t$Should Brazil grant amnesty to people convicted over the 8 January 2023 attacks in Brasilia?$t$,$b$Supporters of Jair Bolsonaro stormed the Congress, Supreme Court and presidential palace in 2023, and hundreds were convicted. Congress has debated amnesty bills. Supporters say sentences were excessive for many rioters. Opponents say amnesty would reward an attempt to overturn an election and invite future coups.$b$),
 (106,'russia',$t$Should Russia keep fining people simply for searching online for materials it lists as extremist?$t$,$b$A 2025 law introduced fines for knowingly searching for and accessing material on Russia's federal extremist list, including via VPN. Officials say it helps fight extremism. Critics note the list includes opposition groups and LGBT organisations, so the law punishes reading rather than acting and chills access to information.$b$),
 (107,'pakistan',$t$Should Pakistan allow military courts to try civilians accused of attacking army installations?$t$,$b$After the 9 May 2023 riots, civilians were tried in military courts, which the Supreme Court later allowed. Supporters say attacks on the army need swift, firm justice. Critics say military courts lack independence and transparency and that civilians should face ordinary courts with full fair-trial rights.$b$),
 (108,'mexico',$t$Should Mexico expand mandatory pretrial detention to more crimes including extortion and fuel theft?$t$,$b$Mexico's constitution lists crimes where suspects are jailed automatically until trial, and a 2024 reform added more. Supporters say it stops dangerous suspects from fleeing. Critics, including the Inter-American Court, say it jails people for years without conviction and violates the presumption of innocence.$b$),
 (109,'japan',$t$Should Japan's local authorities refuse permits for new Muslim burial cemeteries such as the one in Hiji, Oita?$t$,$b$Japan cremates nearly all its dead, and Muslims have few places to bury their dead. Plans for a Muslim cemetery in Hiji, Oita, were stalled by local opposition in 2024 and 2025. Opponents cite groundwater worries. Supporters say burial is a religious necessity and that safety concerns can be handled with regulation.$b$),
 (110,'nigeria',$t$Should Kano State carry out the Sharia court death sentence for blasphemy against Yahaya Sharif-Aminu?$t$,$b$In 2020 a Kano Sharia court sentenced musician Yahaya Sharif-Aminu to death for blasphemy over a WhatsApp song, and his appeal reached the Supreme Court. Supporters say it follows Sharia law adopted by the state. Critics say it violates the constitution's free speech and religious freedom guarantees.$b$),
 (111,'philippines',$t$Should the Philippines lower the minimum age of criminal responsibility from 15 to 9?$t$,$b$A 2019 House bill proposed this, arguing syndicates use children for crimes. Child rights groups, UNICEF and doctors argued it would jail very young children in poor facilities without reducing crime, and the Senate did not pass it.$b$),
 (112,'egypt',$t$Should Egypt prosecute TikTok influencers under the family values clause of its cybercrime law?$t$,$b$Law 175 of 2018 punishes violating Egyptian family values, a vague term. Young women influencers have been jailed over dance and lifestyle videos. Supporters say it guards public morals; critics say it criminalises women's speech and dress.$b$),
 (113,'vietnam',$t$Should Vietnam restore the death penalty for embezzlement it abolished in 2025?$t$,$b$Vietnam dropped capital punishment for embezzlement and some other crimes in 2025, after the Truong My Lan fraud case. Some argue it deterred corruption; opponents say executions are irreversible and asset recovery works better.$b$),
 (114,'germany',$t$Should Germany strip citizenship from dual nationals convicted of antisemitic or extremist crimes?$t$,$b$Union politicians proposed this after the 2024 citizenship reform eased dual nationality. Supporters say citizenship requires loyalty; critics say it creates two classes of Germans and punishes some more harshly based on origin.$b$),
 (115,'bangladesh',$t$Should Bangladesh declare the Ahmadiyya community non-Muslim by law?$t$,$b$Some Islamist groups demand this, as Pakistan did in 1974. Supporters cite theological views; Ahmadis and rights groups say it would strip a small minority of religious freedom and expose them to attacks like those in Panchagarh in 2023.$b$),
 (116,'turkey',$t$Should Turkey criminalise conduct 'contrary to biological sex' as proposed in draft Turkish penal code changes?$t$,$b$A 2025 draft judicial package proposed prison terms for public behaviour or advocacy deemed contrary to biological sex and public morality. Supporters frame it as protecting the family. Critics say it would criminalise LGBT people and activists for their identity and speech.$b$),
 (117,'iran',$t$Should Iran withdraw from the Nuclear Non-Proliferation Treaty, as some Majlis members propose?$t$,$b$After military strikes and the return of UN sanctions, hardline MPs have pushed an NPT exit bill. Backers say the treaty brought no protection. Critics warn it would end inspections, raise the risk of war and nuclear proliferation in the region, and deepen the country's isolation.$b$),
 (118,'united-kingdom',$t$Should the UK abolish indefinite leave to remain, including for migrants already settled here?$t$,$b$Reform UK proposed scrapping ILR and requiring renewed visas, even for people who already hold it. Supporters say it cuts welfare costs. Critics say retroactively removing settled status from hundreds of thousands of lawful residents and families would be unjust and destabilising.$b$),
 (119,'thailand',$t$Should Thailand deport Uyghur asylum seekers held in immigration detention back to China?$t$,$b$Thailand deported 40 Uyghur men to China in 2025 after holding them for over a decade. Officials said it followed diplomatic assurances. UN experts and rights groups say returnees face persecution in Xinjiang and that deportation breaches the principle of non-refoulement.$b$),
 (120,'france',$t$Should France reserve social housing and benefits for French citizens under 'national preference'?$t$,$b$The Rassemblement National proposes prioritising French nationals for jobs, housing and welfare. Supporters say citizens should come first. Critics say it discriminates against legal residents who pay taxes and would likely violate the Constitution and EU law.$b$),
 (121,'italy',$t$Should Italy keep prosecuting citizens who use surrogacy abroad under its 2024 universal crime law?$t$,$b$A 2024 law made surrogacy a crime for Italians even where it is legal abroad, with prison terms and heavy fines. The government says it protects women from exploitation. Critics say it mainly targets same-sex couples, punishes parents after the child is born, and leaves children in legal limbo over recognition of their parents.$b$),
 (122,'south-africa',$t$Should South African public hospitals and clinics refuse treatment to undocumented foreign nationals?$t$,$b$Groups such as Operation Dudula have stationed members at clinics to turn away foreigners, and some politicians want this made official policy. Supporters say overstretched facilities should serve citizens first. Health workers and rights groups say the Constitution guarantees emergency care to everyone and exclusion spreads disease.$b$),
 (123,'south-korea',$t$Should South Korea abolish the Ministry of Gender Equality and Family?$t$,$b$Former President Yoon Suk Yeol pledged to abolish the ministry, arguing structural gender discrimination no longer exists and appealing to young male voters. The ministry runs programs on domestic violence, single-parent families and multicultural families. Critics say scrapping it would weaken support for victims in a country with a large gender pay gap.$b$),
 (124,'spain',$t$Should Spain carry out Vox's proposed mass deportation of millions of immigrants, including legal residents?$t$,$b$In 2025 Vox proposed the remigration of up to eight million immigrants and their descendants who do not integrate. Vox says immigration drives insecurity and wage pressure. Critics note migrants sustain Spain's labour force and pensions, most are lawful residents or citizens, and mass expulsion would breach EU and constitutional law.$b$),
 (125,'colombia',$t$Should Colombia recriminalise abortion after the Constitutional Court's 2022 ruling allowing it up to 24 weeks?$t$,$b$Ruling C-055 of 2022 decriminalised abortion up to 24 weeks and after that in cases of risk to life, rape or fetal non-viability. Conservative lawmakers and religious groups have pushed bills and a referendum to reverse it. Health groups say criminalisation drove unsafe abortions and prosecutions that fell mostly on poor and rural women.$b$),
 (126,'china',$t$Should China make its national online identity ID mandatory for all internet users?$t$,$b$In 2025 China launched a voluntary state-issued cyberspace ID that lets people log into apps without giving platforms their personal data. Making it mandatory would give authorities a single record of each person's online activity. Supporters cite fraud prevention and privacy from companies; critics see a tool for tracking and silencing dissent.$b$),
 (127,'india',$t$Should Indian states require prior approval from a magistrate before a person changes religion?$t$,$b$Several states including Uttar Pradesh, Madhya Pradesh and Gujarat have anti-conversion laws requiring notice or permission to convert, with prison terms for forced or fraudulent conversion. Supporters say they stop coercion and inducement. Critics say they are used against Christians and interfaith couples and violate freedom of conscience.$b$),
 (128,'united-states',$t$Should the United States military bar transgender people from serving?$t$,$b$A 2025 policy moved to discharge most transgender service members and bar new enlistment, which the Supreme Court allowed to take effect. Supporters cite medical readiness and cost. Opponents say thousands of qualified troops are being removed based on identity rather than performance, harming both them and the force.$b$),
 (129,'indonesia',$t$Should Indonesia let active military officers hold more civilian government posts under the 2025 TNI law?$t$,$b$A 2025 revision of the armed forces (TNI) law widened the civilian ministries and agencies active officers can serve in, sparking student protests. Supporters say it uses military skills in government. Critics say it revives the dwifungsi dual role of the Suharto era and weakens civilian control and democracy.$b$),
 (130,'brazil',$t$Should Brazil lower the age of criminal responsibility from 18 to 16?$t$,$b$Brazil tries under-18s under the Statute of Children and Adolescents, with a maximum of three years of socio-educational detention. Proposed constitutional amendments would let 16- and 17-year-olds be tried as adults for serious crimes. Supporters cite violent crime by teens. Opponents say overcrowded adult prisons would recruit youths into gangs.$b$),
 (131,'russia',$t$Should Russia lift its moratorium and resume carrying out the death penalty for terrorism?$t$,$b$Russia has not executed anyone since 1996. After the 2024 Crocus City Hall attack, several Duma deputies called for restoring capital punishment. Supporters see it as deterrence and justice for victims. Opponents point to wrongful convictions, the Constitutional Court's rulings, and that there is little evidence executions deter terrorism.$b$),
 (132,'pakistan',$t$Should Pakistan repeal the Transgender Persons (Protection of Rights) Act 2018?$t$,$b$The 2018 law lets transgender people self-identify their gender on ID cards. In 2023 the Federal Shariat Court struck down key parts, and religious parties want it repealed entirely. Supporters say it clashes with Islamic law. Opponents say repeal would leave khawaja sira communities without protection from discrimination.$b$),
 (133,'mexico',$t$Should Mexico lower the age at which teenagers recruited by cartels can be tried as adults?$t$,$b$Legislators have proposed trying minors aged 14 and up as adults for serious crimes like homicide, as cartels recruit teenagers. Supporters say criminals exploit lenient juvenile law. Opponents say these teens are often victims of forced recruitment and that harsher sentences will not stop cartels from using children.$b$),
 (134,'japan',$t$Should Japan deport asylum seekers after their third rejected application, even during appeals?$t$,$b$A 2023 revision of the immigration law allows deportation of people on their third or later asylum application. The government says repeated claims are used to avoid removal. Critics say Japan recognises very few refugees, making rejections unreliable, and that people could be sent back to persecution.$b$),
 (135,'nigeria',$t$Should Nigeria's federal government again suspend X, formerly Twitter, nationwide?$t$,$b$Nigeria suspended Twitter for seven months in 2021 after it deleted a post by President Buhari. The ECOWAS court ruled the ban unlawful. Supporters say platforms spread fake news and threats to national unity. Critics say it harmed businesses, hit free expression, and was pointless as millions used VPNs.$b$),
 (136,'philippines',$t$Should the Philippine National Police resume Oplan Tokhang house-to-house drug operations?$t$,$b$Tokhang saw police knock on suspected users' doors under the Duterte drug war, which left thousands dead and is under ICC investigation. Some officials say it cut drug use; rights groups link it to killings of unarmed suspects without trial.$b$),
 (137,'egypt',$t$Should Egypt's new Criminal Procedure Law expand police powers to search and detain suspects?$t$,$b$Parliament passed a new code in 2025 replacing the 1950 law. The state says it modernises trials; rights groups and the Bar Association said it keeps near-indefinite pretrial detention, limits defence access and weakens safeguards.$b$),
 (138,'vietnam',$t$Should Vietnam require every social media user to verify identity and let authorities access the data?$t$,$b$Decree 147 of 2024 requires phone-number verification and platform cooperation with state requests. Officials say it curbs fraud and fake news; critics say it removes online anonymity and exposes critics to surveillance and arrest.$b$),
 (139,'germany',$t$Should German police turn back asylum seekers at land borders even when they request asylum?$t$,$b$Since May 2025 the interior ministry ordered pushbacks at borders, and a Berlin court found one case unlawful under EU rules. Supporters say it curbs irregular migration; critics say it breaks EU law and strains neighbouring states.$b$),
 (140,'bangladesh',$t$Should Bangladesh send Rohingya refugees back to Myanmar's Rakhine State even without safety guarantees?$t$,$b$Over a million Rohingya live in Cox's Bazar camps. Many Bangladeshis want them gone given costs and falling aid. The UN says Rakhine, now largely under the Arakan Army amid war, is not safe and forced return would break refoulement rules.$b$),
 (141,'turkey',$t$Should Turkey adopt a 'foreign agent of influence' law criminalising acting in the interests of foreign powers?$t$,$b$A 2024 proposal would have punished people who carry out research or activity serving foreign strategic interests. Supporters cite espionage threats. Journalists, academics and NGOs say its vague wording could be used to jail critics and was shelved after an outcry but may return.$b$),
 (142,'iran',$t$Should Iran continue mass deportations of Afghan migrants, including long-term residents?$t$,$b$Over a million Afghans were expelled in 2025, with officials citing security and economic pressure. Supporters want undocumented migrants removed. Rights groups say many were born or raised in Iran, face Taliban persecution on return, and were targeted by collective suspicion after the war with Israel.$b$),
 (143,'united-kingdom',$t$Should the UK ban wearing the burqa and other face-covering veils in public?$t$,$b$A Reform UK MP raised a burqa ban in Parliament in 2025, citing security and integration, as France and Denmark have done. Opponents say it targets a small number of Muslim women, restricts religious freedom and would criminalise people for what they wear.$b$),
 (144,'thailand',$t$Should Thailand dissolve political parties that campaign to amend the Article 112 lese-majeste law?$t$,$b$The Constitutional Court dissolved Move Forward in 2024 over its plan to amend the law and banned its leaders from politics. Supporters say the monarchy must be protected. Critics say punishing a party for a legislative proposal disenfranchises millions of voters.$b$),
 (145,'france',$t$Should France scrap the 'excuse de minorite' so offenders aged 16 and 17 get adult sentences?$t$,$b$French law normally halves sentences for minors. Politicians including Gabriel Attal have proposed removing this for older teens after violent crimes. Supporters want tougher deterrence. Critics say it breaks with child justice principles and that harsher prison terms raise reoffending.$b$),
 (146,'italy',$t$Should Italy's security decree make passive resistance by prisoners and migrants in detention a crime?$t$,$b$The 2025 security package created a new offence of riot in prisons and migrant centres that covers non-violent disobedience, with multi-year sentences. The government says it restores order in overcrowded facilities. Lawyers, the UN and opposition parties say it criminalises peaceful protest by people already under state control.$b$),
 (147,'south-africa',$t$Should South Africa withdraw from the International Criminal Court?$t$,$b$The government tried to leave in 2016 after failing to arrest Omar al-Bashir, but the High Court blocked it for skipping Parliament. The idea resurfaced over the Putin arrest warrant. Supporters say the ICC unfairly targets African leaders. Critics say leaving would weaken accountability for atrocities and damage South Africa's standing.$b$),
 (148,'south-korea',$t$Should South Korea strip local election voting rights from Chinese permanent residents?$t$,$b$Since 2006, foreigners with permanent residency for three years can vote in local elections, and Chinese nationals are the largest group. People Power Party lawmakers have proposed restricting this on reciprocity grounds, since Koreans cannot vote in China. Critics say it singles out one nationality and fuels anti-Chinese sentiment.$b$),
 (149,'spain',$t$Should Spain repeal its Democratic Memory Law and stop state-funded exhumations of Franco-era mass graves?$t$,$b$The 2022 law funds exhumation of Civil War and dictatorship victims, voids Francoist convictions and bans groups exalting the regime. PP and Vox have repealed regional versions, calling it divisive. Families of victims, over 100,000 of whom are still in unmarked graves, say ending it would deny them the right to recover their relatives.$b$),
 (150,'colombia',$t$Should Colombia convene a constituent assembly to rewrite the 1991 Constitution, as Gustavo Petro has floated?$t$,$b$Petro has suggested a constituent assembly after Congress blocked parts of his reform agenda. Supporters say reforms on land, health and labour are otherwise impossible. Opponents, including former constitutional judges, say it risks undermining checks and balances and that the 1991 Constitution already protects broad social rights.$b$),
 (151,'china',$t$Should China legalise same-sex marriage, as delegates have proposed at the National People's Congress?$t$,$b$Same-sex relationships are legal in China but unions are not recognised, and LGBT advocacy groups have been closed in recent years. Proposals to legalise marriage have been submitted at the NPC and rejected. Supporters say it gives couples equal rights over property, medical decisions and inheritance; opponents cite tradition and concerns about the birth rate.$b$),
 (152,'india',$t$Should India criminalise marital rape by removing the marital exception in the Bharatiya Nyaya Sanhita?$t$,$b$Indian law still exempts forced sex by a husband with an adult wife from the definition of rape, and the question is before the Supreme Court. Supporters say married women deserve equal protection. The central government has argued criminalisation could be misused and destabilise marriage, preferring other remedies.$b$),
 (153,'united-states',$t$Should the United States reschedule marijuana from Schedule I to Schedule III?$t$,$b$Marijuana is legal for adults in about half of US states but federally ranked alongside heroin. Moving it to Schedule III would ease research and let cannabis businesses deduct costs on taxes. Supporters say it matches medical evidence; opponents say it sends the wrong message about youth use and addiction risks.$b$),
 (154,'indonesia',$t$Should Indonesia abolish the death penalty for drug trafficking?$t$,$b$Indonesia has executed foreign and local drug traffickers by firing squad, and the new criminal code allows death sentences to be commuted after ten years of good behaviour. Supporters of abolition say executions have not reduced drug crime and risk killing the wrongly convicted. Opponents say harsh penalties are needed against a drug emergency.$b$),
 (155,'brazil',$t$Should Brazil keep racial and social quotas for admission to federal universities?$t$,$b$Brazil's 2012 Quota Law reserves half of federal university places for public school students, with a share for Black, brown and Indigenous applicants, and was renewed in 2023. Supporters say it has diversified universities without hurting quality. Critics say race categories are hard to define and quotas should be based on income alone.$b$),
 (156,'russia',$t$Should Russia pass a federal law on preventing domestic violence with protection orders?$t$,$b$Russia partially decriminalised first-offence domestic battery in 2017 and has no law on protection orders. Rights groups and some deputies back a bill giving victims restraining orders. Conservative and Orthodox groups say it would undermine the traditional family and allow the state to interfere in private life.$b$),
 (157,'pakistan',$t$Should Pakistan set 18 as the minimum marriage age for both sexes in every province?$t$,$b$Sindh and Islamabad set 18 as the legal minimum, but other provinces still allow girls to marry at 16. The Council of Islamic Ideology has called such laws un-Islamic. Supporters cite health, schooling and child rights. Opponents say marriage age should follow religious guidance and families.$b$),
 (158,'mexico',$t$Should Mexico pass a law to regulate a legal market for recreational cannabis?$t$,$b$The Supreme Court ruled in 2021 that banning personal cannabis use is unconstitutional, but Congress never passed a regulation law. Supporters say regulation would weaken cartels and end arbitrary arrests. Opponents fear more youth use and say a legal market would not stop cartels from dominating.$b$),
 (159,'japan',$t$Should Japan allow married couples to keep separate surnames if they choose?$t$,$b$Japanese law requires married couples to share one surname, and in practice most women take their husband's name. Supporters say an optional choice harms nobody and helps women's careers. Conservatives in the LDP say it would weaken family unity and the koseki family register.$b$),
 (160,'nigeria',$t$Should all 36 Nigerian states adopt the Violence Against Persons (Prohibition) Act?$t$,$b$The 2015 VAPP Act criminalises rape, female genital mutilation and domestic violence, but applies only in the capital unless states adopt it, and some northern states have not. Supporters say survivors everywhere need protection. Some opponents say it conflicts with Sharia or customary law in their states.$b$),
 (161,'philippines',$t$Should the Philippines legalise absolute divorce for married couples?$t$,$b$The Philippines is the only country besides Vatican City without divorce; only costly annulment exists. The House passed a divorce bill in 2024. Supporters cite abused spouses trapped in marriages; the Catholic Church and opponents say it harms families.$b$),
 (162,'egypt',$t$Should Egypt criminalise marrying off girls under 18 with prison terms for parents and officials?$t$,$b$A cabinet bill would punish guardians and clerks who arrange underage marriages, common through unregistered customary contracts in rural areas. Supporters cite girls' health and schooling; some conservatives call it state interference in families.$b$),
 (163,'vietnam',$t$Should Vietnam legally recognise same-sex marriage and give couples equal rights?$t$,$b$Vietnam removed its ban on same-sex weddings in 2015 but does not recognise them, leaving couples without inheritance, adoption or medical decision rights. Supporters cite fairness and polling; opponents cite tradition and family structure.$b$),
 (164,'germany',$t$Should Germany legalise abortion in early pregnancy by removing it from Section 218 of the Criminal Code?$t$,$b$Abortion is technically unlawful but unpunished up to 12 weeks after counselling. A government commission in 2024 recommended legalising it early on. Supporters say it ends stigma; Christian Democrats and churches want the compromise kept.$b$),
 (165,'bangladesh',$t$Should Bangladesh adopt an optional civil family law giving women equal inheritance?$t$,$b$The 2025 Women's Affairs Reform Commission proposed a uniform family code. Supporters say women get half the inheritance of men under current religious law; Hefazat rallied against it, saying it contradicts the Quran.$b$),
 (166,'turkey',$t$Should Turkey rejoin the Istanbul Convention on preventing violence against women?$t$,$b$Turkey withdrew by presidential decree in 2021, with officials arguing the treaty undermined family values. Women's groups say rejoining would restore legal commitments on protection orders and prosecution in a country with hundreds of femicides a year. Opponents object to its gender language.$b$),
 (167,'iran',$t$Should Iran lift its filtering of Instagram, Telegram and other blocked platforms?$t$,$b$WhatsApp and Google Play were unblocked in late 2024 but many platforms remain filtered and millions use VPNs. Supporters say blocking hurts small online businesses and fails anyway. Security officials argue open platforms enable foreign influence and protest organising.$b$),
 (168,'united-kingdom',$t$Should the UK lower the voting age to 16 for UK general elections?$t$,$b$The government plans to extend the vote to 16 and 17 year olds, as in Scotland and Wales for devolved elections. Supporters say young people pay taxes and can work. Critics argue they lack maturity and suspect the change is designed to help parties popular with the young.$b$),
 (169,'thailand',$t$Should Thailand legalise and regulate sex work instead of banning it under the 1996 Prostitution Act?$t$,$b$Sex work is illegal but widespread and tied to tourism. A draft bill would recognise sex workers' rights. Supporters say legalisation brings labour protection, health access and less police extortion. Opponents fear it would normalise exploitation and increase trafficking.$b$),
 (170,'france',$t$Should France build six new EPR2 nuclear reactors to replace its ageing fleet?$t$,$b$EDF plans six EPR2 reactors at Penly, Gravelines and Bugey. Supporters say nuclear keeps French electricity low-carbon and secure. Opponents cite the delays and cost overruns at Flamanville, the unsolved waste problem, and prefer investment in renewables.$b$),
 (171,'italy',$t$Should Italy grant citizenship to children of immigrants who complete a school cycle in Italy (ius scholae)?$t$,$b$Children born in Italy to foreign parents must wait until 18 to apply. Ius scholae would let those who complete about five years of Italian schooling become citizens earlier. Supporters say they are already Italian in every practical way. Opponents on the right say citizenship rules are already generous and the 2025 referendum on the topic failed.$b$),
 (172,'south-africa',$t$Should South Africa legalise a regulated commercial cannabis market beyond private home use?$t$,$b$The Cannabis for Private Purposes Act of 2024 allows adults to grow and use cannabis at home but not to sell it. Supporters say legal sales would create rural jobs, tax revenue and an industry for Eastern Cape growers. Opponents worry about youth use, impaired driving and whether regulators can control a commercial market.$b$),
 (173,'south-korea',$t$Should South Korea pass a comprehensive anti-discrimination act covering sexual orientation and gender identity?$t$,$b$Bills have been proposed in the National Assembly since 2007 and the National Human Rights Commission backs them, but none has passed. Supporters say Korea is one of few OECD countries without such a law. Conservative Protestant groups argue it would restrict religious freedom and speech, and lawmakers have avoided a vote.$b$),
 (174,'spain',$t$Should Spain grant an extraordinary regularisation to around 500,000 undocumented migrants already living there?$t$,$b$A citizens' legislative initiative backed by over 600,000 signatures and the Catholic Church was admitted by Congress in 2024. Supporters say most already work in farming and care and legal status would add tax revenue and reduce exploitation. Opponents, led by Vox, say it would encourage more irregular arrivals.$b$),
 (175,'colombia',$t$Should Colombia enforce its national ban on bullfighting starting in 2027?$t$,$b$Congress passed a law in 2024 banning bullfighting, with a three-year transition, after Bogota had already ended it. Supporters say animal suffering should not be entertainment. Breeders and fans in cities like Manizales and Cali say it destroys cultural tradition and rural livelihoods, and the law offers limited support to affected workers.$b$),
 (176,'china',$t$Should China allow unmarried women to freeze their eggs at public hospitals?$t$,$b$Chinese rules restrict egg freezing to married women with medical needs, and a Beijing woman lost a high-profile lawsuit over it. Supporters say single women deserve the same reproductive options and that it may help the falling birth rate. Opponents argue it encourages delayed childbearing and raises ethical and health concerns.$b$),
 (177,'india',$t$Should India's Parliament legalise same-sex marriage after the Supreme Court declined to in 2023?$t$,$b$In Supriyo v Union of India the Supreme Court refused to recognise same-sex marriage, leaving it to Parliament. Supporters say couples need rights over inheritance, adoption and medical consent. The government and many religious groups argue marriage is between a man and a woman and that the issue is for society, not courts.$b$),
 (178,'united-states',$t$Should the United States ban members of Congress from trading individual stocks?$t$,$b$Members of Congress may buy and sell stocks, only required to disclose trades under the STOCK Act. Bipartisan bills would require blind trusts or diversified funds. Supporters say lawmakers profit from inside knowledge and it erodes trust. Opponents say it restricts private rights and deters wealthy candidates.$b$),
 (179,'indonesia',$t$Should Indonesia legalise medical cannabis for patients with serious illnesses?$t$,$b$Cannabis is a Class I narcotic in Indonesia, with no medical use allowed. A mother's petition for her son with cerebral palsy reached the Constitutional Court, which rejected it in 2022 but urged research. Supporters cite evidence for epilepsy and pain. Opponents fear abuse and conflict with religious norms.$b$),
 (180,'brazil',$t$Should Brazil decriminalise possession of small amounts of marijuana for personal use?$t$,$b$In 2024 the Supreme Federal Court ruled possession of up to 40 grams of cannabis for personal use is not a crime, while Congress has pushed an amendment to criminalise all possession. Supporters say it reduces mass incarceration of poor, Black youths. Opponents say it encourages drug use and trafficking.$b$),
 (181,'russia',$t$Should Russia repeal its foreign agent law and remove journalists and NGOs from the registry?$t$,$b$The Ministry of Justice registry labels hundreds of media outlets, NGOs and individuals as foreign agents, imposing labels, audits and bans on teaching or state funding. Supporters of the law say it guards against foreign interference. Critics say it is used to silence independent journalists and critics of the war.$b$),
 (182,'pakistan',$t$Should Pakistan lift the ban on student unions at its colleges and universities?$t$,$b$Student unions have been banned since 1984 under General Zia ul Haq. Sindh passed a law to restore them but has not held elections. Supporters say unions train future leaders and give students a voice. Opponents fear a return of armed campus violence linked to party wings.$b$),
 (183,'mexico',$t$Should Mexico ban the sale of junk food and sugary drinks in all its schools?$t$,$b$From 2025 the government banned sale of ultra-processed food and sugary drinks in schools. Supporters point to Mexico's high child obesity and diabetes rates. Opponents, including snack vendors and some parents, say it hurts small traders, is hard to enforce, and that the issue is better handled by families.$b$),
 (184,'japan',$t$Should Japan legalise same-sex marriage following several high court rulings on the issue?$t$,$b$Japan is the only G7 country without legal recognition of same-sex couples, and several high courts have ruled the ban unconstitutional. Supporters say it gives equal rights for inheritance, hospital visits and housing. Opponents, mainly conservatives, say marriage is defined as between a man and a woman.$b$),
 (185,'nigeria',$t$Should Nigeria reserve special seats for women in the National Assembly and state assemblies?$t$,$b$Women hold under five percent of seats in Nigeria's National Assembly. The Special Seats Bill would create extra seats reserved for women. Supporters say it is the fastest way to raise representation. Opponents say it is tokenism, costly and should be won at the ballot box, and some religious leaders object.$b$),
 (186,'philippines',$t$Should the Philippine Congress pass the SOGIE Equality Bill against anti-LGBT discrimination?$t$,$b$The bill would bar discrimination based on sexual orientation or gender identity in jobs, schools and services. It has stalled for over two decades. Supporters cite documented discrimination; religious groups say it threatens religious freedom.$b$),
 (187,'egypt',$t$Should Egypt's personal status law require a husband to notify his wife before taking a second wife?$t$,$b$A draft family law would require informing existing wives and courts of a new marriage, giving wives grounds for divorce. Women's groups want polygamy limits; conservative clerics say it restricts a right permitted in Islamic law.$b$),
 (188,'vietnam',$t$Should Vietnam pass the Gender Affirmation Law letting transgender people change legal gender?$t$,$b$A 2015 civil code change allowed legal gender change but the detailed law has stalled for years. Supporters say trans people face job and paperwork discrimination; opponents raise concerns about surgery rules, minors and social readiness.$b$),
 (189,'germany',$t$Should Germany keep its 2024 cannabis legalisation instead of repealing it?$t$,$b$Adults may grow and carry limited cannabis and join social clubs. The CDU pledged to reverse the law. Supporters say it reduces black market sales and police workload; critics cite youth health risks and continued illegal trade.$b$),
 (190,'bangladesh',$t$Should Bangladesh scrap speech offences like defamation and hurting religious sentiment from its cyber laws?$t$,$b$The Digital Security Act and Cyber Security Act were used to jail journalists and critics. A 2025 ordinance dropped some offences. Supporters want all speech crimes removed; others say they protect religion and against online hate.$b$),
 (191,'turkey',$t$Should Turkey allow Kurdish as a language of instruction in public schools in the southeast?$t$,$b$Kurdish is currently offered only as an elective and in private courses. Supporters say mother-tongue teaching improves learning for millions of Kurdish children and would support the peace process. Opponents fear it would weaken national unity and the constitutional status of Turkish.$b$),
 (192,'iran',$t$Should Iran guarantee women full access to men's football matches at Azadi Stadium and elsewhere?$t$,$b$Women were barred from stadiums for decades, and access remains limited and inconsistent despite FIFA pressure. Supporters say it is a basic equality issue. Conservative clerics argue mixed crowds in stadiums conflict with religious rules on modesty.$b$),
 (193,'united-kingdom',$t$Should the UK ban conversion practices aimed at changing a person's sexual orientation or gender identity?$t$,$b$Ministers have promised a trans-inclusive ban after years of delay. Supporters cite evidence of harm from so-called therapies. Some religious groups and gender-critical campaigners worry it could criminalise prayer or cautious clinical and parental conversations with young people.$b$),
 (194,'thailand',$t$Should Thailand's Senate be directly elected instead of chosen through the current indirect selection system?$t$,$b$Under the 2017 constitution senators are picked through a complex multi-level selection process that critics say is opaque and open to manipulation. Supporters of direct election say it gives voters a real say. Opponents want an upper house insulated from party politics.$b$),
 (195,'france',$t$Should France return colonial-era artefacts in its museums to African countries that request them?$t$,$b$France returned the Abomey treasures to Benin and the talking drum to Cote d'Ivoire, and a framework law on restitution has been debated. Supporters say the objects were taken by force. Critics worry about emptying museums and bypassing the inalienability of national collections.$b$),
 (196,'italy',$t$Should Italian registry offices list both parents of same-sex couples on their children's birth certificates?$t$,$b$In 2023 the Interior Ministry told city registries such as Milan and Padua to stop registering the non-biological parent. The Constitutional Court ruled in 2025 that two mothers can be recognised. Supporters say it protects children's inheritance and custody rights. Opponents argue it bypasses the ban on surrogacy and adoption rules.$b$),
 (197,'south-africa',$t$Should South Africa pass the Marriage Bill giving Muslim, Hindu and other religious marriages full legal recognition?$t$,$b$The Constitutional Court ruled in 2022 that the lack of recognition for Muslim marriages is unconstitutional. The Marriage Bill would create one law covering civil, customary and religious marriages. Supporters say it protects women on divorce or death. Some religious conservatives object to state involvement and to its inclusion of polygamous unions.$b$),
 (198,'south-korea',$t$Should South Korea repeal Military Criminal Act Article 92-6, which punishes consensual sex between male soldiers?$t$,$b$The provision punishes sexual acts between soldiers with up to two years in prison. The Supreme Court ruled in 2022 it cannot apply to consensual acts off base, but the Constitutional Court has upheld the law. The military says it is needed for discipline. Rights groups say it targets gay men and is unnecessary alongside general conduct rules.$b$),
 (199,'spain',$t$Should Spain cut the legal working week from 40 to 37.5 hours with no loss of pay?$t$,$b$Labour Minister Yolanda Diaz's bill was rejected by Congress in 2025 after PP, Vox and Junts voted against it. Supporters say Spain's productivity gains justify shorter hours and better work-life balance. Employer groups say small businesses in hospitality and retail cannot absorb the cost and it should be left to collective bargaining.$b$),
 (200,'colombia',$t$Should Colombia's Congress pass a statutory law regulating euthanasia and medically assisted death?$t$,$b$Colombia was the first Latin American country to allow euthanasia, through Constitutional Court rulings since 1997, but Congress has never passed a law. Supporters say clear rules would protect patients and doctors. Religious groups and some lawmakers oppose any expansion, while others say court rulings alone leave hospitals uncertain.$b$),
 (201,'china',$t$Should China keep issuing Chinese names for places in Arunachal Pradesh, which it calls Zangnan?$t$,$b$China has published several lists of standardised Chinese names for towns, rivers and mountains in Arunachal Pradesh, an Indian state it claims. India rejects the lists as meaningless. Supporters in China see it as asserting sovereignty; critics say renaming on maps changes nothing on the ground and only inflames relations with India.$b$),
 (202,'india',$t$Should India drop the name India and use only Bharat in all official and international use?$t$,$b$The constitution says India, that is Bharat, and G20 invitations in 2023 used President of Bharat. Supporters say Bharat reflects indigenous heritage rather than a colonial-era name. Critics say a rebrand would be costly, symbolic and a distraction, with no effect on citizens' daily lives.$b$),
 (203,'united-states',$t$Should the United States officially rename the Gulf of Mexico the Gulf of America?$t$,$b$A 2025 executive order renamed the gulf in federal usage, and the Associated Press was barred from some White House events for not adopting it. Supporters call it a patriotic assertion. Critics call it a pointless provocation of Mexico; ships, fisheries and weather are unchanged whatever the maps say.$b$),
 (204,'indonesia',$t$Should Indonesian schools require singing all three stanzas of the anthem Indonesia Raya?$t$,$b$Indonesia Raya is usually sung with only its first stanza. A 2017 government push encouraged schools to sing all three stanzas to strengthen nationalism. Supporters say it restores the song's full meaning. Critics say it is a symbolic gesture that adds minutes to ceremonies without changing civic knowledge or behaviour.$b$),
 (205,'brazil',$t$Should Brazil ban gender-neutral language such as todes in schools and government documents?$t$,$b$Several Brazilian states and cities passed laws banning neutral forms like todes or todxs in schools, some struck down by the Supreme Court. Supporters say it protects standard Portuguese. Critics say few people use neutral language anyway and the fight is symbolic, with little effect on how anyone is taught.$b$),
 (206,'russia',$t$Should Russia restore the statue of Felix Dzerzhinsky to Lubyanka Square in Moscow?$t$,$b$The statue of the Soviet secret police founder was removed from outside the FSB headquarters in 1991. Communists and some officials want it returned, and copies have since gone up elsewhere. Supporters see it as history and order. Opponents see it as honouring the architect of the Red Terror. It would change little in daily life.$b$),
 (207,'pakistan',$t$Should Pakistan ban public celebrations of Valentine's Day as un-Islamic?$t$,$b$In 2017 the Islamabad High Court banned Valentine's Day celebrations in public places and in the media, and some officials repeat the call each year. Supporters say it is a foreign custom against local values. Critics say it is moral policing that does nothing to address real social problems.$b$),
 (208,'mexico',$t$Should Mexico keep demanding a formal apology from Spain for the conquest of the Aztec Empire?$t$,$b$In 2019 President Lopez Obrador asked King Felipe VI to apologise for the conquest, and the dispute led Mexico to snub the king at Sheinbaum's 2024 inauguration. Supporters say it recognises Indigenous suffering. Critics say it is symbolic, harms diplomatic ties, and does little for Indigenous communities today.$b$),
 (209,'japan',$t$Should Japan's prime minister visit Yasukuni Shrine in person on the 15 August anniversary?$t$,$b$Yasukuni honours Japan's war dead, including convicted Class-A war criminals. Supporters say leaders should honour those who died for Japan. China and South Korea protest every visit, and critics say it glorifies wartime aggression. In practice the visit is symbolic and changes no policy.$b$),
 (210,'nigeria',$t$Should Nigeria scrap Nigeria, We Hail Thee and return to the Arise O Compatriots anthem?$t$,$b$In 2024 the government replaced the 1978 anthem Arise O Compatriots with the colonial-era Nigeria, We Hail Thee. Supporters of reversal say the old anthem was written by Nigerians. Supporters of the change say it restores national heritage. Critics on both sides note it does nothing to address insecurity or inflation.$b$),
 (211,'philippines',$t$Should the Philippines rename the country Maharlika to drop its colonial Spanish name?$t$,$b$The name honours King Philip II of Spain. Rodrigo Duterte floated Maharlika in 2019, as Marcos Sr had before. Supporters see decolonisation; critics say the cost of rebranding is high and the Marcos link to the word makes it divisive.$b$),
 (212,'egypt',$t$Should Egypt formally demand that the British Museum return the Rosetta Stone?$t$,$b$Egyptian archaeologists and petitions have called for the stone, taken by Britain in 1801, to go to the Grand Egyptian Museum. Supporters see it as colonial loot; critics say it is mainly symbolic and diverts from protecting sites at home.$b$),
 (213,'vietnam',$t$Should Vietnam ban foreign films that show China's nine-dash line map of the South China Sea?$t$,$b$Vietnam banned Barbie in 2023 and other films over maps showing Beijing's claimed line. Supporters say it defends sovereignty; critics say it barely affects the real dispute at sea and makes censorship boards more arbitrary.$b$),
 (214,'germany',$t$Should German states ban gender-inclusive spelling like the gender star in schools and offices?$t$,$b$Bavaria, Hesse and others banned forms like Lehrer*innen in official use. Supporters say it defends standard German; critics say it is symbolic politics over punctuation that barely affects equality or how people speak day to day.$b$),
 (215,'bangladesh',$t$Should Bangladesh replace its national anthem Amar Sonar Bangla by Rabindranath Tagore?$t$,$b$In 2024 some Islamist figures called for a new anthem, saying Tagore's song was imposed and does not reflect independence. Defenders say it is part of 1971 heritage; critics say the debate is symbolic and distracts from reforms.$b$),
 (216,'turkey',$t$Should Istanbul's Hagia Sophia be turned back into a museum after its 2020 reconversion to a mosque?$t$,$b$A 2020 court ruling and decree ended its museum status. Secularists and many abroad want the 1934 status restored. Supporters of the mosque say it honours the 1453 conquest. In practice the building stays open to tourists outside prayer times either way.$b$),
 (217,'iran',$t$Should Iran remove four zeros from the rial and rename the currency the toman?$t$,$b$Parliament approved redenomination in 2025 after years of debate. Supporters say it simplifies prices already quoted informally in tomans. Critics say it is cosmetic and does nothing about the inflation that destroyed the rial's value in the first place.$b$),
 (218,'united-kingdom',$t$Should the British Museum return the Parthenon Marbles to Greece?$t$,$b$The sculptures were removed from Athens by Lord Elgin in the early 1800s. Greece wants them back. Supporters say they belong with the Acropolis. Opponents fear a precedent for emptying museums, and the British Museum Act currently bars disposal. Few people outside the two museums would notice.$b$),
 (219,'thailand',$t$Should Thailand require cinema audiences to stand for the royal anthem before every film?$t$,$b$Cinemas play the royal anthem and audiences are expected to stand, with occasional prosecutions of people who stayed seated. Supporters see it as respect for the monarchy. Critics call it compelled loyalty. It changes very little beyond a few minutes before each screening.$b$),
 (220,'france',$t$Should France delete the word 'race' from Article 1 of the French Constitution?$t$,$b$Article 1 guarantees equality regardless of origin, race or religion. Removal was voted by deputies in 2018 but never completed. Supporters say races do not exist biologically. Critics say removing the word does nothing against racism and could weaken anti-discrimination protection.$b$),
 (221,'italy',$t$Should Italian schools and ministries ban the schwa and asterisks as gender-neutral endings in official documents?$t$,$b$Italy's Education Ministry and Accademia della Crusca have discouraged forms like tutt* or tuttə in official texts. Supporters say standard Italian must stay clear and readable. Critics say it is a symbolic fight about inclusion. In practice very few official documents ever used these forms, so little would actually change.$b$),
 (222,'south-africa',$t$Should South Africa reverse the renaming of Port Elizabeth to Gqeberha?$t$,$b$The city was officially renamed Gqeberha in 2021, part of a wider move to replace colonial-era place names. Opponents say it was costly and imposed without enough consultation. Supporters say it restores the isiXhosa name. The metro, Nelson Mandela Bay, is unchanged, and the renaming has little effect on services or the economy.$b$),
 (223,'south-korea',$t$Should Seoul build a memorial hall for former President Syngman Rhee at Songhyeon Green Plaza?$t$,$b$Conservative groups and the Seoul city government pushed to build a hall honouring Rhee, Korea's first president, near Gyeongbokgung Palace. Supporters credit him with founding the republic and the US alliance. Opponents cite his authoritarian rule and the April 1960 uprising. The dispute is intense but mostly about historical memory.$b$),
 (224,'spain',$t$Should Spain add official lyrics to its national anthem, the Marcha Real?$t$,$b$Spain's anthem is one of the few in the world with no official words. The Spanish Olympic Committee tried in 2007 but the proposed lyrics were withdrawn after a public backlash. Supporters say athletes deserve words to sing. Critics say no text could unite Castilian, Catalan and Basque identities. Nothing practical would change.$b$),
 (225,'colombia',$t$Should Bogota restore the statues of Christopher Columbus and Queen Isabella removed after 2021 protests?$t$,$b$During the 2021 national strike, Misak Indigenous protesters toppled a statue of conquistador Sebastian de Belalcazar in Popayan and targeted the Columbus statue in Bogota, which the city then removed. Supporters say they are heritage. Indigenous groups see them as symbols of conquest. The fight is symbolic and changes no policy.$b$),
 (226,'china',$t$Should Chinese schools and local governments discourage Christmas celebrations as a Western festival?$t$,$b$Some Chinese cities, universities and schools have told staff and students not to hold Christmas events, citing cultural confidence and the need to promote traditional festivals. Supporters say it protects Chinese culture; critics say it is a symbolic fight over decorations and shopping that barely affects anyone's life.$b$),
 (227,'india',$t$Should New Delhi rename roads and places named after Mughal rulers such as Aurangzeb and Akbar?$t$,$b$Aurangzeb Road became APJ Abdul Kalam Road in 2015, and groups have petitioned to rename Akbar Road, Humayun Road and other Delhi streets. Supporters say the Mughals should not be honoured. Critics call it rewriting history to target Muslim heritage, and note that signage changes do nothing for residents.$b$),
 (228,'united-states',$t$Should the United States Army restore former base names such as Fort Bragg and Fort Hood?$t$,$b$Bases once named after Confederate officers were renamed in 2023, then given back their old names in 2025 by honouring different soldiers with the same surnames. Supporters say the old names carry tradition. Critics say it honours the Confederacy by the back door; either way it is a signage fight with little practical effect.$b$),
 (229,'indonesia',$t$Should Indonesian cities ban Valentine's Day celebrations in schools and public places?$t$,$b$Cities and regencies such as Banda Aceh, Makassar and Surabaya have issued bans or warnings against Valentine's Day events, calling them un-Islamic or Western. Supporters say it protects youth morals. Critics say it is a yearly culture-war ritual that barely affects anyone, since people celebrate privately anyway.$b$),
 (230,'brazil',$t$Should Brazil add the word Amor to the Ordem e Progresso motto on its national flag?$t$,$b$A bill in Congress proposed restoring the full Positivist motto by adding Amor to the flag's Ordem e Progresso. Supporters say it would make the flag more inclusive and humane. Critics say changing the flag is costly, divisive and purely symbolic, especially as the flag has become a partisan emblem.$b$),
 (231,'russia',$t$Should Russia rename the city of Volgograd back to Stalingrad permanently?$t$,$b$The city was renamed from Stalingrad in 1961. It already uses the old name on certain war anniversaries, and in 2025 Vladimir Putin suggested a referendum. Supporters say it honours the 1942 to 1943 battle. Opponents say it glorifies Stalin and would cost money to change documents for no real benefit.$b$),
 (232,'pakistan',$t$Should Pakistan make 9 November, Iqbal Day, a national public holiday every year?$t$,$b$Iqbal Day, marking the poet Allama Muhammad Iqbal's birthday, was dropped as a holiday in 2015, restored in 2022, and remains argued over. Supporters say it honours the national poet. Critics say extra holidays cost the economy and that honouring Iqbal does not need a day off.$b$),
 (233,'mexico',$t$Should Mexico City permanently replace the Columbus statue on Paseo de la Reforma with an Indigenous woman?$t$,$b$The Columbus statue was removed in 2020 and the city planned to replace it with a sculpture of an Olmec woman. Supporters say the city should honour Indigenous people instead of a colonist. Opponents say it erases history and heritage. The change is symbolic and affects little beyond the monument.$b$),
 (234,'japan',$t$Should Japan require all public school teachers to stand and sing the Kimigayo anthem at ceremonies?$t$,$b$Tokyo and Osaka require teachers to stand for Kimigayo at graduation, and many have been disciplined for refusing. Supporters say respect for national symbols is basic. Opponents say the anthem is tied to wartime emperor worship and that forcing it violates freedom of conscience.$b$),
 (235,'nigeria',$t$Should Nigeria change its official name to the United African Republic?$t$,$b$A 2023 petition to the National Assembly argued that the name Nigeria was coined by a colonial writer and proposed United African Republic. Supporters say it breaks with colonialism. Opponents say it would be costly, confusing and irrelevant to the country's economic and security problems.$b$),
 (236,'philippines',$t$Should Philippine government offices be required to sing the Bagong Pilipinas hymn at flag ceremonies?$t$,$b$A 2024 memorandum from President Marcos Jr ordered agencies and schools to recite the Bagong Pilipinas hymn and pledge. Backers say it builds unity; critics call it political branding of the administration that changes nothing in governance.$b$),
 (237,'egypt',$t$Should Egypt require all shop signs in Cairo and other cities to be written in Arabic?$t$,$b$Parliamentary proposals to protect Arabic would fine businesses using foreign-language names and signs. Backers say English signage erodes national identity; critics say it burdens business and tourism while doing little for Arabic literacy.$b$),
 (238,'vietnam',$t$Should Vietnam officially rename Ho Chi Minh City back to Saigon?$t$,$b$The city was renamed in 1976 after reunification, yet many residents still say Saigon. After the 2025 provincial merger, some raised the idea again. Supporters cite local identity; others see the current name as a key historical symbol.$b$),
 (239,'germany',$t$Should Berlin keep the new name Anton-Wilhelm-Amo-Strasse for the former Mohrenstrasse?$t$,$b$The street, whose old name used an archaic term for Black people, was renamed in 2025 after an African-born German philosopher. Supporters see a step on colonial history; opponents and residents fought it in court as costly symbolism.$b$),
 (240,'bangladesh',$t$Should Bangladesh remove Sheikh Mujibur Rahman's portrait from all banknotes?$t$,$b$The central bank began issuing notes in 2025 with landscapes and heritage sites instead of the founding leader. Supporters say it ends a personality cult; critics say it erases the independence leader and the redesign costs money.$b$),
 (241,'turkey',$t$Should Turkey require shop signs in Istanbul and other cities to be mainly in Turkish rather than English?$t$,$b$Officials and nationalist groups have pushed rules limiting foreign words on storefronts, citing protection of the Turkish language. Business owners say foreign branding attracts tourists and customers. The change would alter signage but little about how businesses actually operate.$b$),
 (242,'iran',$t$Should Iran restore the pre-1979 Lion and Sun emblem to its national flag?$t$,$b$The emblem was replaced after the revolution and is now a symbol for monarchists and much of the diaspora. Supporters see it as an older national symbol. Opponents see it as tied to the Pahlavi dynasty. Changing the flag would alter little about how Iran is governed.$b$),
 (243,'united-kingdom',$t$Should UK councils be allowed to fly only the Union flag and national flags on public buildings?$t$,$b$Several Reform-led councils banned Pride, Palestinian and other flags in 2025, and 'Operation Raise the Colours' spread flags on lampposts. Supporters see it as neutrality and patriotism. Critics call it divisive. Either way it changes no services or laws.$b$),
 (244,'thailand',$t$Should Thailand officially use Krung Thep Maha Nakhon instead of Bangkok as the capital's English name?$t$,$b$In 2022 the Royal Institute listed Krung Thep Maha Nakhon as the formal name with Bangkok in brackets, sparking online debate. Supporters say it reflects the name Thais actually use. Critics say it is confusing for tourists and business. Daily life is unaffected.$b$),
 (245,'france',$t$Should France ban inclusive writing (ecriture inclusive) in official documents and schools?$t$,$b$Forms like 'etudiant.e.s' are already discouraged by government circular, and the Senate voted a ban in 2023. Supporters, including the Academie francaise, defend the language. Opponents say it makes women visible. The practical effect on public life is marginal.$b$),
 (246,'italy',$t$Should crucifixes be removed from the walls of Italian public school classrooms?$t$,$b$Rules dating back to the 1920s put crucifixes in classrooms, and the European Court of Human Rights upheld them in Lautsi v Italy in 2011. Secular groups say a state school should be neutral. Defenders call it a cultural symbol of Italian identity. Teaching, curriculum and religious education choices would be unaffected either way.$b$),
 (247,'south-africa',$t$Should South Africa remove the Afrikaans Die Stem section from its national anthem?$t$,$b$Since 1997 the anthem has combined Nkosi Sikelel iAfrika with part of Die Stem, the apartheid-era anthem. The EFF and others call for it to be dropped as a relic of oppression. Defenders say the blend was a deliberate symbol of reconciliation under Mandela. Changing it would not alter any law, budget or public service.$b$),
 (248,'south-korea',$t$Should the Korea Military Academy relocate the bust of independence fighter Hong Beom-do from its campus?$t$,$b$In 2023 the academy and Defence Ministry moved to relocate the bust, citing Hong's later membership in the Soviet Communist Party. Opponents called it an insult to the independence movement, and the plan stalled amid protests. The fight is fierce in parliament and the press but has no effect on military training or policy.$b$),
 (249,'spain',$t$Should Spain proceed with the resignification of the Valley of Cuelgamuros, formerly the Valley of the Fallen?$t$,$b$Franco's remains were removed in 2019 and the government plans to redesign the monument as a site of remembrance, keeping the basilica and giant cross. The right sees it as erasing history, while some victims' groups want it demolished. The project is loudly debated but mostly concerns one monument's interpretation.$b$),
 (250,'colombia',$t$Should the M-19 guerrilla flag be banned from official Colombian presidential events?$t$,$b$President Petro, a former M-19 member, has displayed the group's flag at public events, including the 2025 rally with Bolivar's sword. Critics say it honours a group responsible for the 1985 Palace of Justice siege. Supporters say M-19 signed a peace deal in 1990 and helped write the Constitution. The dispute is about symbols only.$b$)
  ) AS t(ord, forum, title, body)
  JOIN forums f ON f.slug = t.forum;

COMMIT;

-- What you should see: 250 questions, 25 forums with 10 each, 0 ballots,
-- 5 test agents, and 0 titles that are not questions.
SELECT (SELECT count(*) FROM issues) AS questions,
       (SELECT count(DISTINCT forum_id) FROM issues) AS forums_used,
       (SELECT count(*) FROM issues WHERE forum_id IS NULL) AS without_forum,
       (SELECT count(*) FROM votes)  AS ballots,
       (SELECT count(*) FROM agents a JOIN users u ON u.id = a.user_id
         WHERE u.email LIKE '%@dd.test') AS test_agents,
       (SELECT count(*) FROM issues WHERE title NOT LIKE '%?') AS titles_not_questions;
